package org.transittr.tests;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
public final class ExpandedCitiesCheck extends Instrumentation {
 private Activity activity;private ClassLoader loader;
 private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 private Class<?> type(String n)throws Exception{return loader.loadClass("org.transittr."+n);}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void set(String n,Object v)throws Exception{Field f=activity.getClass().getDeclaredField(n);f.setAccessible(true);f.set(activity,v);}
 private void invoke(String n)throws Exception{Method m=activity.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(activity);}
 private void status(String value){Bundle b=new Bundle();b.putString("stream",value+"\n");sendStatus(1,b);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();boolean pass=false;try{
  activity=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));loader=activity.getClassLoader();waitForIdleSync();Class<?> registry=type("CityRegistry");Object[] cities=(Object[])registry.getField("ALL").get(null);check(cities.length==67,"all public ASIS cities plus existing providers and Bursa");check(((Boolean)type("WidgetFavorites").getMethod("valid",Integer.TYPE,String.class,String.class,String.class).invoke(null,1010,"3074","201","")).booleanValue(),"new city accepted by widget");
  Object catalog=type("CatalogStore").getConstructor(Context.class).newInstance(activity);Object page=type("CatalogStore").getMethod("page",Integer.TYPE,Integer.TYPE,String.class,Integer.TYPE).invoke(catalog,1010,0,"",0);check(((Integer)field(page,"total")).intValue()==403,"Balikesir catalogue");Object client=type("AsisCityClient").getMethod("forCity",Integer.TYPE).invoke(null,1010);Object live=client.getClass().getMethod("query",String.class,String.class,Boolean.TYPE).invoke(client,"3074","",false);check(field(live,"rows") instanceof ArrayList,"ASIS stop arrivals queried");status("ASIS_CITIES=60;BALIKESIR_ROUTES=403;ARRIVALS="+((ArrayList)field(live,"rows")).size());
  Object route=type("BursaClient").getMethod("route",String.class,String.class).invoke(null,"19E","19E");check(((ArrayList)field(route,"parts")).size()>0&&((ArrayList)field(route,"stops")).size()>50,"Bursa real geometry and stop sequence");status("BURSA_ROUTE_STOPS="+((ArrayList)field(route,"stops")).size());Object filtered=type("BursaClient").getMethod("query",String.class,String.class,Boolean.TYPE).invoke(null,"3368","D3",true);status("BURSA_FILTERED_ROWS="+((ArrayList)field(filtered,"rows")).size());
  runOnMainSync(new Runnable(){public void run(){try{invoke("stopTracking");set("city",Integer.valueOf(9));set("screen",Integer.valueOf(0));set("snapshot",null);invoke("build");((EditText)field(activity,"stopInput")).setText("3368");((EditText)field(activity,"lineInput")).setText("");((Button)field(activity,"start")).performClick();}catch(Exception e){throw new RuntimeException(e);}}});
  Object data=null;for(int i=0;i<300;i++){Thread.sleep(200);data=field(activity,"snapshot");if(data!=null)break;}check(data!=null,"Bursa UI live query");int gps=((Integer)data.getClass().getMethod("positionCount").invoke(data)).intValue();ArrayList rows=(ArrayList)field(data,"rows");check(gps>0&&rows.size()>0,"Bursa GPS and stop arrivals");status("BURSA_LIVE_GPS="+gps+";ARRIVALS="+rows.size());status("CAPTURE=BURSA_LIVE");Thread.sleep(5000);pass=true;result.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; CITY_REGISTRY=67; BURSA_GPS_AND_ROUTE=true; ASIS_STOP_QUERY=true\n");
 }catch(Throwable e){java.io.StringWriter w=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(w));result.putString("stream","FAIL Android "+Build.VERSION.SDK_INT+"\n"+w);}finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
